-- Generated by `npm run content:sync` from src/content/. Do not edit by hand.
-- Never edit this file once applied; run content:sync again to make a new one.

on conflict (id) do update set
  mode = excluded.mode,
  public_payload = excluded.public_payload,
  answer_key = excluded.answer_key,
  active = true;

-- Items removed from src/content/ stay in the table (old rounds reference them) but are
-- never picked again.
update public.content_items
set active = false
where id not in ('soc-001', 'soc-002', 'soc-003', 'soc-004', 'soc-005', 'soc-006', 'soc-007', 'soc-008', 'soc-009', 'soc-010', 'soc-011', 'soc-012', 'soc-013', 'soc-014', 'soc-015', 'soc-016', 'soc-017', 'soc-018', 'trv-001', 'trv-002', 'trv-003', 'trv-004', 'trv-005', 'trv-006', 'trv-007', 'trv-008', 'trv-009', 'trv-010', 'trv-011', 'trv-012', 'trv-013', 'trv-014', 'trv-015', 'trv-016', 'trv-017', 'trv-018', 'wrd-001', 'wrd-002', 'wrd-003', 'wrd-004', 'wrd-005', 'wrd-006', 'wrd-007', 'wrd-008', 'wrd-009', 'wrd-010', 'wrd-011', 'wrd-012', 'wrd-013', 'wrd-014', 'wrd-015', 'wrd-016', 'wrd-017', 'wrd-018');
